    row=json.loads(line)
    if row.get('status')!='complete': continue
    ids=[]
    v=row.get('evidence_run_id')
    if isinstance(v,str) and v.strip() and not v.startswith('none:'): ids.append(v.strip())
    detail=row.get('detail')
    entries=detail.get('evidence') if isinstance(detail,dict) else None
    for e in entries or []:
        if isinstance(e,dict):
            r=e.get('run_id')
            if isinstance(r,str) and not r.startswith('none:'): ids.append(r)
    for r in ids:
        total+=1
        hits=[p for p in tracked if p.endswith('/'+r+'/verdict.json')]
        if not hits: missing.append((row['id'],r))
print('cited run ids on complete rows:', total)
print('bindings whose verdict.json is NOT tracked:', len(missing))
for m in missing[:20]: print(m)
